mapper.select:
SELECT T.SEQNO, T.CREDIT_FLAG creditFlag, T.CREDIT_MST_ID creditMstId, T.PFLSH,T.HAP_CREDIT_AMT hapCreditAmt, T.CREDIT_AMT creditAmt,MAX(T.VDATE) VDATE,T.CUSTOMER_ID customerId, T.TERM term FROM CREDIT_LINES T WHERE (((
T.CUSTOMER_ID =( SELECT case when T2.Type_8 = '${fzq}' then T1.ISSUER when T2.Type_8 = '${fck}' then T1.ISSUER when T2.Type_8 = '${fxml}' then T1.FINANCIER when T2.Type_8 = '${fhg}', then #{dto.counterId,jdbcType=VARCHAR}, else T1.MANAGER end FROM FIN_PRODUCT T1 INNER JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID WHERE T1.FINPROD_ID = #{dto.finprodId,jdbcType=VARCHAR})
T.CUSTOMER_ID = #{parentCustomId,jdbcType=VARCHAR}
AND T.CREDIT_MST_ID = #{creditmstidJG,jdbcType=VARCHAR} ))
OR (
T.CUSTOMER_ID = (SELECT case when T2.Type_8 = '${fzq}' then T1.ISSUER when T2.Type_8 = '${fck}' then T1.ISSUER when T2.Type_8 = '${fxml}' then T1.FINANCIER when T2.Type_8 = '${fhg}', then #{dto.counterId,jdbcType=VARCHAR}, else T1.MANAGER end FROM FIN_PRODUCT T1 INNER JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID WHERE T1.FINPROD_ID = #{dto.finprodId,jdbcType=VARCHAR})
T.CUSTOMER_ID = #{parentCustomId,jdbcType=VARCHAR}
AND T.CREDIT_MST_ID IN
#{item}
)
) AND T.VDATE = (select max(tt.vdate) from CREDIT_LINES tt where t.credit_mst_id = tt.credit_mst_id and t.customer_id = tt.customer_id and #{dto.tradeDate,jdbcType=DATE}>=tt.vdate) AND #{dto.tradeDate,jdbcType=DATE} >=T.VDATE
AND T.MDATE >=#{dto.tradeDate,jdbcType=DATE}
GROUP BY T.SEQNO,T.CREDIT_FLAG,T.CREDIT_MST_ID,T.PFLSH,T.HAP_CREDIT_AMT,T.CREDIT_AMT,T.CUSTOMER_ID, T.TERM

select TTT.SEQNO, TTT.CREDIT_FLAG, TTT.CREDIT_MST_ID, TTT.PFLSH,(TTT.hapCreditAmt+IFNULL(TEMP1.hapCreditAmt,0)) hapCreditAmt,TTT.creditAmt,TTT.VDATE,TTT.CUSTOMER_ID,TTT.CREDIT_CONDITION
FROM (
SELECT T.SEQNO, T.CREDIT_FLAG, T.CREDIT_MST_ID, T.PFLSH,T.HAP_CREDIT_AMT hapCreditAmt,T.CREDIT_AMT creditAmt,MAX(T.VDATE) VDATE,T.CUSTOMER_ID,T.CREDIT_CONDITION
FROM CREDIT_LINES T
WHERE (((T.CUSTOMER_ID =#{dto.counterId,jdbcType=VARCHAR}
AND T.CREDIT_MST_ID = #{creditmstidJG,jdbcType=VARCHAR}
))
OR
(T.CUSTOMER_ID =#{dto.counterId,jdbcType=VARCHAR}
AND T.CREDIT_MST_ID =(select seqno from CREDIT_MST_INFO T5
where trim(concat(IFNULL(T5.credit_quote_type_code,''), IFNULL(T5.CREDIT_QUOTE_TYPE_VALUE,''))) in
(select trim(concat(IFNULL(dict_code,''), IFNULL(item_code,''))) from SYS_DATADICT_LIST_LINK
start with trim(concat((IFNULL(linked_dict_code,''), IFNULL(dict_code,'')),IFNULL(item_code,''))) =trim(concat((concat('PINAN_ASSET_TYPE', 'TARGET_BACK_TYPE')),IFNULL(#{repType},'')))
connect by trim(concat(IFNULL(linked_dict_code,''), IFNULL(linked_item_code,''))) = prior trim(concat(IFNULL(dict_code,''), IFNULL(item_code,'')))
))
)
)
AND T.VDATE = (select max(tt.vdate)
from CREDIT_LINES tt
where t.credit_mst_id = tt.credit_mst_id
and t.customer_id = tt.customer_id
and #{dto.tradeDate,jdbcType=DATE}>=tt.vdate)
AND #{dto.tradeDate,jdbcType=DATE} >=T.VDATE

    AND T.MDATE >=#{dto.tradeDate,jdbcType=DATE}

GROUP BY T.SEQNO,T.CREDIT_FLAG,T.CREDIT_MST_ID,T.PFLSH,T.HAP_CREDIT_AMT,T.CREDIT_AMT,T.CUSTOMER_ID,T.CREDIT_CONDITION)TTT
LEFT JOIN (
SELECT T.SEQNO,T.CREDIT_MST_ID,

    T.CREDIT_AMT hapCreditAmt,


    0 hapCreditAmt,

MAX(T.VDATE),T.CUSTOMER_ID
FROM CREDIT_LINES_PRE T
WHERE (((T.CUSTOMER_ID =#{dto.counterId,jdbcType=VARCHAR}
AND T.CREDIT_MST_ID = #{creditmstidJG,jdbcType=VARCHAR}
))
OR
(T.CUSTOMER_ID =#{dto.counterId,jdbcType=VARCHAR}
AND T.CREDIT_MST_ID =(select seqno from CREDIT_MST_INFO T5
where trim(concat(IFNULL(T5.credit_quote_type_code,''), IFNULL(T5.CREDIT_QUOTE_TYPE_VALUE,''))) in
(select trim(concat(IFNULL(dict_code,''), IFNULL(item_code,''))) from SYS_DATADICT_LIST_LINK
start with trim(concat((concat(IFNULL(linked_dict_code,''), IFNULL(dict_code,''))),IFNULL(item_code,''))) =trim(concat((concat('PINAN_ASSET_TYPE', 'TARGET_BACK_TYPE')),#{repType}))
connect by trim(concat(IFNULL(linked_dict_code,''), IFNULL(linked_item_code,''))) = prior trim(concat(IFNULL(dict_code,''), IFNULL(item_code,'')))
))
)
)
AND T.VDATE = (select max(tt.vdate)
from CREDIT_LINES_PRE tt
where t.credit_mst_id = tt.credit_mst_id
and t.customer_id = tt.customer_id
and #{dto.tradeDate,jdbcType=DATE}>=tt.vdate)
AND #{dto.tradeDate,jdbcType=DATE} >=T.VDATE
AND T.MDATE >=#{dto.tradeDate,jdbcType=DATE}
GROUP BY T.SEQNO,T.CREDIT_MST_ID,T.CREDIT_AMT,T.CUSTOMER_ID
) temp1 ON TTT.CUSTOMER_ID=temp1.CUSTOMER_ID and TTT.CREDIT_MST_ID=temp1.CREDIT_MST_ID

SELECT T1.RISK_WEIGHT FROM ( SELECT ASSET_TYPE_ONE, ASSET_TYPE_TWO, RISK_WEIGHT FROM ( SELECT ASSET_TYPE_ONE, ASSET_TYPE_TWO, RISK_WEIGHT, RANK() OVER(PARTITION BY ASSET_TYPE_ONE,ASSET_TYPE_TWO ORDER BY EFF_DATE DESC ) AS rowno FROM RISK_WEIGHT WHERE #{tradedate} >= EFF_DATE ) WHERE rowno=1 ) T1 where 1 = 1
AND T1.ASSET_TYPE_ONE = #{type1}
AND T1.ASSET_TYPE_TWO= #{type2}
